create table public.customers (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, name text not null, phone text, address text, notes text, created_at timestamptz not null default now());
create table public.receivables (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, customer_id uuid not null references public.customers(id), sale_id uuid references public.sales(id), amount numeric(14,2) not null, paid_amount numeric(14,2) not null default 0, due_date date, status text not null default 'OPEN' check(status in ('OPEN','PARTIAL','PAID')), created_at timestamptz not null default now());
create table public.receivable_payments (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, receivable_id uuid not null references public.receivables(id) on delete cascade, amount numeric(14,2) not null, paid_at timestamptz not null default now(), created_by uuid references public.profiles(id));
create index customers_tenant_idx on public.customers(tenant_id); create index receivables_tenant_status_idx on public.receivables(tenant_id,status);
alter table public.customers enable row level security; alter table public.receivables enable row level security; alter table public.receivable_payments enable row level security;
create policy customers_member on public.customers for all using (public.is_tenant_member(tenant_id)) with check (public.is_tenant_member(tenant_id));
create policy receivables_member on public.receivables for all using (public.is_tenant_member(tenant_id)) with check (public.is_tenant_member(tenant_id));
create policy receivable_payments_member on public.receivable_payments for all using (public.is_tenant_member(tenant_id)) with check (public.is_tenant_member(tenant_id));
